   994→// removeAgentHooks removes hooks from all agents that support hooks.
   995→func removeAgentHooks(w io.Writer) error {
   996→	var errs []error
   997→
   998→	// Remove Claude Code hooks
   999→	claudeAgent, err := agent.Get(agent.AgentNameClaudeCode)
  1000→	if err == nil {
  1001→		if hookAgent, ok := claudeAgent.(agent.HookSupport); ok {
  1002→			wasInstalled := hookAgent.AreHooksInstalled()
  1003→			if err := hookAgent.UninstallHooks(); err != nil {
  1004→				errs = append(errs, err)
  1005→			} else if wasInstalled {
  1006→				fmt.Fprintln(w, "  Removed Claude Code hooks")
  1007→			}
  1008→		}
  1009→	}
  1010→
  1011→	// Remove Gemini CLI hooks
  1012→	geminiAgent, err := agent.Get(agent.AgentNameGemini)
  1013→	if err == nil {
  1014→		if hookAgent, ok := geminiAgent.(agent.HookSupport); ok {
  1015→			wasInstalled := hookAgent.AreHooksInstalled()
  1016→			if err := hookAgent.UninstallHooks(); err != nil {
  1017→				errs = append(errs, err)
  1018→			} else if wasInstalled {
  1019→				fmt.Fprintln(w, "  Removed Gemini CLI hooks")
  1020→			}
  1021→		}
  1022→	}
  1023→
  1024→	return errors.Join(errs...)
  1025→}
