  1027→// removeAllSessionStates removes all session state files and the directory.
  1028→func removeAllSessionStates() (int, error) {
  1029→	store, err := session.NewStateStore()
  1030→	if err != nil {
  1031→		return 0, fmt.Errorf("failed to create state store: %w", err)
  1032→	}
  1033→
  1034→	// Count states before removing
  1035→	states, err := store.List(context.Background())
  1036→	if err != nil {
  1037→		return 0, fmt.Errorf("failed to list session states: %w", err)
  1038→	}
  1039→	count := len(states)
  1040→
  1041→	// Remove the entire directory
  1042→	if err := store.RemoveAll(); err != nil {
  1043→		return 0, fmt.Errorf("failed to remove session states: %w", err)
  1044→	}
  1045→
  1046→	return count, nil
  1047→}
