cat > /tmp/test-hook-recognition.go << 'EOF'
package main

import (
	"fmt"
	"strings"
)

var entireHookPrefixes = []string{
	"entire ",
	"go run ${CLAUDE_PROJECT_DIR}/cmd/entire/main.go ",
	"bash ${CLAUDE_PROJECT_DIR}/.claude/scripts/entire-wrapper.sh ",
}

func isEntireHook(command string) bool {
	for _, prefix := range entireHookPrefixes {
		if strings.HasPrefix(command, prefix) {
			return true
		}
	}
	return false
}

func main() {
	testCases := []struct {
		command  string
		expected bool
	}{
		{"entire hooks claude-code stop", true},
		{"go run ${CLAUDE_PROJECT_DIR}/cmd/entire/main.go hooks claude-code stop", true},
		{"bash ${CLAUDE_PROJECT_DIR}/.claude/scripts/entire-wrapper.sh hooks claude-code stop", true},
		{"some-other-command", false},
	}

	allPassed := true
	for _, tc := range testCases {
		result := isEntireHook(tc.command)
		status := "✅"
		if result != tc.expected {
			status = "❌"
			allPassed = false
		}
		fmt.Printf("%s isEntireHook(%q) = %v (expected %v)\n", status, tc.command, result, tc.expected)
	}

	if allPassed {
		fmt.Println("\n✅ All tests passed!")
	} else {
		fmt.Println("\n❌ Some tests failed!")
	}
}
EOF
